-- Playground Bank's schema, as Postgres reports it after every migration in
-- bank/migrations/ has run. Generated by `npm run db:schema`; do not edit.
-- A migration that changes this without regenerating it fails the suite.

CREATE TABLE bank_api_key_usage (
  key_id uuid NOT NULL,
  minute timestamp with time zone NOT NULL,
  count integer NOT NULL DEFAULT 0,
  CONSTRAINT bank_api_key_usage_pkey PRIMARY KEY (key_id, minute),
  CONSTRAINT bank_api_key_usage_key_id_fkey FOREIGN KEY (key_id) REFERENCES bank_api_keys(id) ON DELETE CASCADE
);

CREATE TABLE bank_api_keys (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  name text NOT NULL,
  scope text NOT NULL,
  token_hash text NOT NULL,
  prefix text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  last_used_at timestamp with time zone,
  revoked_at timestamp with time zone,
  CONSTRAINT bank_api_keys_pkey PRIMARY KEY (id),
  CONSTRAINT bank_api_keys_token_hash_key UNIQUE (token_hash),
  CONSTRAINT bank_api_keys_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_api_keys_scope_check CHECK ((scope = ANY (ARRAY['read'::text, 'write'::text])))
);
CREATE INDEX bank_api_keys_user ON public.bank_api_keys USING btree (user_id, created_at);

CREATE TABLE bank_bill_payments (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  account_id uuid NOT NULL,
  payee_id uuid NOT NULL,
  amount_cents bigint NOT NULL,
  memo text NOT NULL DEFAULT ''::text,
  idempotency_key text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_bill_payments_pkey PRIMARY KEY (id),
  CONSTRAINT bank_bill_payments_user_id_idempotency_key_key UNIQUE (user_id, idempotency_key),
  CONSTRAINT bank_bill_payments_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_bill_payments_payee_id_fkey FOREIGN KEY (payee_id) REFERENCES bank_payees(id) ON DELETE CASCADE,
  CONSTRAINT bank_bill_payments_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE
);

CREATE TABLE bank_card_charges (
  id uuid NOT NULL,
  card_id uuid NOT NULL,
  merchant text NOT NULL,
  amount_cents bigint NOT NULL,
  status text NOT NULL,
  reason text,
  charged_on date NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_card_charges_pkey PRIMARY KEY (id),
  CONSTRAINT bank_card_charges_card_id_fkey FOREIGN KEY (card_id) REFERENCES bank_cards(id) ON DELETE CASCADE,
  CONSTRAINT bank_card_charges_amount_cents_check CHECK ((amount_cents > 0)),
  CONSTRAINT bank_card_charges_reason_check CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['frozen'::text, 'over_limit'::text, 'insufficient_funds'::text])))),
  CONSTRAINT bank_card_charges_status_check CHECK ((status = ANY (ARRAY['approved'::text, 'declined'::text])))
);
CREATE INDEX bank_card_charges_card_day ON public.bank_card_charges USING btree (card_id, charged_on, status);
CREATE INDEX bank_card_charges_card_newest ON public.bank_card_charges USING btree (card_id, created_at, id);

CREATE TABLE bank_cards (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  account_id uuid NOT NULL,
  number text NOT NULL,
  expires text NOT NULL,
  cvv text NOT NULL,
  status text NOT NULL DEFAULT 'active'::text,
  frozen_by text,
  limit_cents bigint NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_cards_pkey PRIMARY KEY (id),
  CONSTRAINT bank_cards_account_id_key UNIQUE (account_id),
  CONSTRAINT bank_cards_number_key UNIQUE (number),
  CONSTRAINT bank_cards_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_cards_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_cards_frozen_by_check CHECK (((frozen_by IS NULL) OR (frozen_by = ANY (ARRAY['customer'::text, 'admin'::text])))),
  CONSTRAINT bank_cards_limit_cents_check CHECK ((limit_cents >= 0)),
  CONSTRAINT bank_cards_status_check CHECK ((status = ANY (ARRAY['active'::text, 'frozen'::text])))
);
CREATE INDEX bank_cards_user ON public.bank_cards USING btree (user_id, created_at);

CREATE TABLE bank_clocks (
  user_id uuid NOT NULL,
  offset_days integer NOT NULL DEFAULT 0,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_clocks_pkey PRIMARY KEY (user_id),
  CONSTRAINT bank_clocks_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_clocks_offset_days_check CHECK ((offset_days >= 0))
);

CREATE TABLE bank_coins (
  symbol text NOT NULL,
  name text NOT NULL,
  anchor_micros bigint NOT NULL,
  volatility numeric(6,4) NOT NULL,
  drift numeric(6,4) NOT NULL,
  depth_atoms bigint NOT NULL,
  rank integer NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_coins_pkey PRIMARY KEY (symbol),
  CONSTRAINT bank_coins_anchor_micros_check CHECK ((anchor_micros > 0)),
  CONSTRAINT bank_coins_depth_atoms_check CHECK ((depth_atoms > 0)),
  CONSTRAINT bank_coins_drift_check CHECK ((drift >= (0)::numeric)),
  CONSTRAINT bank_coins_volatility_check CHECK ((volatility > (0)::numeric))
);
CREATE INDEX bank_coins_rank ON public.bank_coins USING btree (rank);

CREATE TABLE bank_holdings (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  quantity_atoms bigint NOT NULL DEFAULT 0,
  cost_cents bigint NOT NULL DEFAULT 0,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_holdings_pkey PRIMARY KEY (id),
  CONSTRAINT bank_holdings_user_id_symbol_key UNIQUE (user_id, symbol),
  CONSTRAINT bank_holdings_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_holdings_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_holdings_cost_cents_check CHECK ((cost_cents >= 0)),
  CONSTRAINT bank_holdings_quantity_atoms_check CHECK ((quantity_atoms >= 0))
);
CREATE INDEX bank_holdings_user ON public.bank_holdings USING btree (user_id, symbol);

CREATE TABLE bank_loans (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  account_id uuid NOT NULL,
  amount_cents bigint NOT NULL,
  term_months integer NOT NULL,
  apr_basis_points integer NOT NULL,
  monthly_payment_cents bigint NOT NULL,
  total_interest_cents bigint NOT NULL,
  purpose text NOT NULL DEFAULT ''::text,
  status text NOT NULL DEFAULT 'pending'::text,
  decided_by uuid,
  decision_note text NOT NULL DEFAULT ''::text,
  decided_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_loans_pkey PRIMARY KEY (id),
  CONSTRAINT bank_loans_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_loans_decided_by_fkey FOREIGN KEY (decided_by) REFERENCES bank_users(id) ON DELETE SET NULL,
  CONSTRAINT bank_loans_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_loans_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
  CONSTRAINT bank_loans_term_months_check CHECK ((term_months = ANY (ARRAY[12, 24, 36, 60])))
);
CREATE INDEX bank_loans_status ON public.bank_loans USING btree (status, created_at);
CREATE INDEX bank_loans_user ON public.bank_loans USING btree (user_id, created_at);

CREATE TABLE bank_login_holds (
  email text NOT NULL,
  client text NOT NULL,
  failures integer NOT NULL DEFAULT 0,
  first_failed_at timestamp with time zone NOT NULL DEFAULT now(),
  held_until timestamp with time zone,
  CONSTRAINT bank_login_holds_pkey PRIMARY KEY (email, client)
);

CREATE TABLE bank_money_accounts (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  number text NOT NULL,
  kind text NOT NULL,
  name text NOT NULL,
  balance_cents bigint NOT NULL DEFAULT 0,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_money_accounts_pkey PRIMARY KEY (id),
  CONSTRAINT bank_money_accounts_number_key UNIQUE (number),
  CONSTRAINT bank_money_accounts_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_money_accounts_kind_check CHECK ((kind = ANY (ARRAY['checking'::text, 'savings'::text])))
);
CREATE INDEX bank_money_accounts_user ON public.bank_money_accounts USING btree (user_id, created_at);

CREATE TABLE bank_money_requests (
  id uuid NOT NULL,
  requester_id uuid NOT NULL,
  to_account_id uuid NOT NULL,
  payer_id uuid NOT NULL,
  payer_account_number text NOT NULL,
  amount_cents bigint NOT NULL,
  memo text NOT NULL DEFAULT ''::text,
  status text NOT NULL DEFAULT 'pending'::text,
  transfer_id uuid,
  answered_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_money_requests_pkey PRIMARY KEY (id),
  CONSTRAINT bank_money_requests_payer_id_fkey FOREIGN KEY (payer_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_money_requests_requester_id_fkey FOREIGN KEY (requester_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_money_requests_to_account_id_fkey FOREIGN KEY (to_account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_money_requests_transfer_id_fkey FOREIGN KEY (transfer_id) REFERENCES bank_transfers(id) ON DELETE SET NULL,
  CONSTRAINT bank_money_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'paid'::text, 'declined'::text, 'cancelled'::text])))
);
CREATE INDEX bank_money_requests_payer ON public.bank_money_requests USING btree (payer_id, created_at);
CREATE INDEX bank_money_requests_requester ON public.bank_money_requests USING btree (requester_id, created_at);

CREATE TABLE bank_notifications (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  kind text NOT NULL,
  title text NOT NULL,
  body text NOT NULL DEFAULT ''::text,
  link text NOT NULL DEFAULT ''::text,
  amount_cents bigint,
  read_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_notifications_pkey PRIMARY KEY (id),
  CONSTRAINT bank_notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_notifications_kind_check CHECK ((kind = ANY (ARRAY['money_received'::text, 'loan_decided'::text, 'account_changed'::text, 'request_received'::text, 'request_answered'::text, 'support_reply'::text, 'support_solved'::text, 'welcome'::text, 'scheduled_paid'::text, 'scheduled_failed'::text, 'card_declined'::text, 'order_filled'::text, 'order_failed'::text, 'price_alert'::text])))
);
CREATE INDEX bank_notifications_unread ON public.bank_notifications USING btree (user_id) WHERE (read_at IS NULL);
CREATE INDEX bank_notifications_user ON public.bank_notifications USING btree (user_id, created_at);

CREATE TABLE bank_orders (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  account_id uuid NOT NULL,
  side text NOT NULL,
  spend_cents bigint,
  quantity_atoms bigint,
  limit_micros bigint NOT NULL,
  status text NOT NULL DEFAULT 'open'::text,
  fill_price_micros bigint,
  trade_id uuid,
  fail_reason text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  filled_at timestamp with time zone,
  CONSTRAINT bank_orders_pkey PRIMARY KEY (id),
  CONSTRAINT bank_orders_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_orders_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_orders_trade_id_fkey FOREIGN KEY (trade_id) REFERENCES bank_trades(id) ON DELETE SET NULL,
  CONSTRAINT bank_orders_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_orders_check CHECK (((spend_cents IS NULL) <> (quantity_atoms IS NULL))),
  CONSTRAINT bank_orders_limit_micros_check CHECK ((limit_micros > 0)),
  CONSTRAINT bank_orders_quantity_atoms_check CHECK (((quantity_atoms IS NULL) OR (quantity_atoms > 0))),
  CONSTRAINT bank_orders_side_check CHECK ((side = ANY (ARRAY['buy'::text, 'sell'::text]))),
  CONSTRAINT bank_orders_spend_cents_check CHECK (((spend_cents IS NULL) OR (spend_cents > 0))),
  CONSTRAINT bank_orders_status_check CHECK ((status = ANY (ARRAY['open'::text, 'filled'::text, 'cancelled'::text, 'failed'::text])))
);
CREATE INDEX bank_orders_open ON public.bank_orders USING btree (user_id, status, created_at);
CREATE INDEX bank_orders_user_newest ON public.bank_orders USING btree (user_id, created_at, id);

CREATE TABLE bank_payees (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  name text NOT NULL,
  reference text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  deleted_at timestamp with time zone,
  CONSTRAINT bank_payees_pkey PRIMARY KEY (id),
  CONSTRAINT bank_payees_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE
);
CREATE INDEX bank_payees_user ON public.bank_payees USING btree (user_id, created_at);

CREATE TABLE bank_price_alerts (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  direction text NOT NULL,
  limit_micros bigint NOT NULL,
  status text NOT NULL DEFAULT 'armed'::text,
  fired_micros bigint,
  fired_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_price_alerts_pkey PRIMARY KEY (id),
  CONSTRAINT bank_price_alerts_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_price_alerts_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_price_alerts_direction_check CHECK ((direction = ANY (ARRAY['above'::text, 'below'::text]))),
  CONSTRAINT bank_price_alerts_limit_micros_check CHECK ((limit_micros > 0)),
  CONSTRAINT bank_price_alerts_status_check CHECK ((status = ANY (ARRAY['armed'::text, 'fired'::text, 'cancelled'::text])))
);
CREATE INDEX bank_price_alerts_armed ON public.bank_price_alerts USING btree (user_id, status, created_at);

CREATE TABLE bank_profiles (
  user_id uuid NOT NULL,
  phone text NOT NULL DEFAULT ''::text,
  address_line text NOT NULL DEFAULT ''::text,
  city text NOT NULL DEFAULT ''::text,
  postal_code text NOT NULL DEFAULT ''::text,
  country text NOT NULL DEFAULT ''::text,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_profiles_pkey PRIMARY KEY (user_id),
  CONSTRAINT bank_profiles_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE
);

CREATE TABLE bank_scheduled_payments (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  account_id uuid NOT NULL,
  payee_id uuid NOT NULL,
  amount_cents bigint NOT NULL,
  memo text NOT NULL DEFAULT ''::text,
  repeat text NOT NULL,
  anchor_day integer NOT NULL,
  next_due date NOT NULL,
  status text NOT NULL DEFAULT 'active'::text,
  runs integer NOT NULL DEFAULT 0,
  last_run_on date,
  last_result text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_scheduled_payments_pkey PRIMARY KEY (id),
  CONSTRAINT bank_scheduled_payments_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_scheduled_payments_payee_id_fkey FOREIGN KEY (payee_id) REFERENCES bank_payees(id) ON DELETE CASCADE,
  CONSTRAINT bank_scheduled_payments_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_scheduled_payments_amount_cents_check CHECK ((amount_cents > 0)),
  CONSTRAINT bank_scheduled_payments_anchor_day_check CHECK (((anchor_day >= 1) AND (anchor_day <= 31))),
  CONSTRAINT bank_scheduled_payments_last_result_check CHECK (((last_result IS NULL) OR (last_result = ANY (ARRAY['paid'::text, 'failed'::text])))),
  CONSTRAINT bank_scheduled_payments_repeat_check CHECK ((repeat = ANY (ARRAY['once'::text, 'weekly'::text, 'monthly'::text]))),
  CONSTRAINT bank_scheduled_payments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'done'::text, 'failed'::text, 'cancelled'::text])))
);
CREATE INDEX bank_scheduled_payments_due ON public.bank_scheduled_payments USING btree (user_id, status, next_due);

CREATE TABLE bank_schema_migrations (
  version integer NOT NULL,
  name text NOT NULL,
  applied_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_schema_migrations_pkey PRIMARY KEY (version)
);

CREATE TABLE bank_sessions (
  token_hash text NOT NULL,
  user_id uuid NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  expires_at timestamp with time zone NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  device text NOT NULL DEFAULT ''::text,
  last_seen_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_sessions_pkey PRIMARY KEY (token_hash),
  CONSTRAINT bank_sessions_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX bank_sessions_id ON public.bank_sessions USING btree (id);
CREATE INDEX bank_sessions_user_id ON public.bank_sessions USING btree (user_id);

CREATE TABLE bank_settings (
  user_id uuid NOT NULL,
  currency text NOT NULL DEFAULT 'USD'::text,
  locale text NOT NULL DEFAULT 'en-US'::text,
  email_alerts boolean NOT NULL DEFAULT true,
  statement_emails boolean NOT NULL DEFAULT false,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_settings_pkey PRIMARY KEY (user_id),
  CONSTRAINT bank_settings_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_settings_currency_check CHECK ((currency = ANY (ARRAY['USD'::text, 'EUR'::text, 'GBP'::text, 'ILS'::text]))),
  CONSTRAINT bank_settings_locale_check CHECK ((locale = ANY (ARRAY['en-US'::text, 'en-GB'::text, 'de-DE'::text])))
);

CREATE TABLE bank_support_messages (
  id uuid NOT NULL,
  seq bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  ticket_id uuid NOT NULL,
  author_id uuid NOT NULL,
  body text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_support_messages_pkey PRIMARY KEY (id),
  CONSTRAINT bank_support_messages_author_id_fkey FOREIGN KEY (author_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_support_messages_ticket_id_fkey FOREIGN KEY (ticket_id) REFERENCES bank_support_tickets(id) ON DELETE CASCADE
);
CREATE INDEX bank_support_messages_ticket ON public.bank_support_messages USING btree (ticket_id, seq);

CREATE TABLE bank_support_tickets (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  subject text NOT NULL,
  transaction_id uuid,
  status text NOT NULL DEFAULT 'open'::text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_support_tickets_pkey PRIMARY KEY (id),
  CONSTRAINT bank_support_tickets_transaction_id_fkey FOREIGN KEY (transaction_id) REFERENCES bank_transactions(id) ON DELETE SET NULL,
  CONSTRAINT bank_support_tickets_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_support_tickets_status_check CHECK ((status = ANY (ARRAY['open'::text, 'answered'::text, 'solved'::text])))
);
CREATE INDEX bank_support_tickets_status ON public.bank_support_tickets USING btree (status, updated_at);
CREATE INDEX bank_support_tickets_user ON public.bank_support_tickets USING btree (user_id, updated_at);

CREATE TABLE bank_swaps (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  from_symbol text NOT NULL,
  to_symbol text NOT NULL,
  from_atoms bigint NOT NULL,
  to_atoms bigint NOT NULL,
  from_price_micros bigint NOT NULL,
  to_price_micros bigint NOT NULL,
  value_cents bigint NOT NULL,
  fee_cents bigint NOT NULL,
  cost_cents bigint NOT NULL DEFAULT 0,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_swaps_pkey PRIMARY KEY (id),
  CONSTRAINT bank_swaps_from_symbol_fkey FOREIGN KEY (from_symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_swaps_to_symbol_fkey FOREIGN KEY (to_symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_swaps_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_swaps_check CHECK ((from_symbol <> to_symbol)),
  CONSTRAINT bank_swaps_fee_cents_check CHECK ((fee_cents >= 0)),
  CONSTRAINT bank_swaps_from_atoms_check CHECK ((from_atoms > 0)),
  CONSTRAINT bank_swaps_from_price_micros_check CHECK ((from_price_micros > 0)),
  CONSTRAINT bank_swaps_to_atoms_check CHECK ((to_atoms > 0)),
  CONSTRAINT bank_swaps_to_price_micros_check CHECK ((to_price_micros > 0))
);
CREATE INDEX bank_swaps_user ON public.bank_swaps USING btree (user_id, created_at);

CREATE TABLE bank_trade_quotes (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  side text NOT NULL,
  spend_cents bigint,
  quantity_atoms bigint,
  price_micros bigint NOT NULL,
  gross_cents bigint NOT NULL,
  fee_cents bigint NOT NULL,
  net_cents bigint NOT NULL,
  filled_atoms bigint NOT NULL,
  expires_at timestamp with time zone NOT NULL,
  used_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_trade_quotes_pkey PRIMARY KEY (id),
  CONSTRAINT bank_trade_quotes_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_trade_quotes_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_trade_quotes_check CHECK (((spend_cents IS NULL) <> (quantity_atoms IS NULL))),
  CONSTRAINT bank_trade_quotes_fee_cents_check CHECK ((fee_cents >= 0)),
  CONSTRAINT bank_trade_quotes_filled_atoms_check CHECK ((filled_atoms > 0)),
  CONSTRAINT bank_trade_quotes_price_micros_check CHECK ((price_micros > 0)),
  CONSTRAINT bank_trade_quotes_side_check CHECK ((side = ANY (ARRAY['buy'::text, 'sell'::text])))
);
CREATE INDEX bank_trade_quotes_user ON public.bank_trade_quotes USING btree (user_id, created_at);

CREATE TABLE bank_trades (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  account_id uuid NOT NULL,
  side text NOT NULL,
  quantity_atoms bigint NOT NULL,
  price_micros bigint NOT NULL,
  gross_cents bigint NOT NULL,
  fee_cents bigint NOT NULL,
  net_cents bigint NOT NULL,
  cost_cents bigint NOT NULL DEFAULT 0,
  quote_id uuid,
  transaction_id uuid,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_trades_pkey PRIMARY KEY (id),
  CONSTRAINT bank_trades_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_trades_quote_id_fkey FOREIGN KEY (quote_id) REFERENCES bank_trade_quotes(id) ON DELETE SET NULL,
  CONSTRAINT bank_trades_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_trades_transaction_id_fkey FOREIGN KEY (transaction_id) REFERENCES bank_transactions(id) ON DELETE SET NULL,
  CONSTRAINT bank_trades_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_trades_fee_cents_check CHECK ((fee_cents >= 0)),
  CONSTRAINT bank_trades_price_micros_check CHECK ((price_micros > 0)),
  CONSTRAINT bank_trades_quantity_atoms_check CHECK ((quantity_atoms > 0)),
  CONSTRAINT bank_trades_side_check CHECK ((side = ANY (ARRAY['buy'::text, 'sell'::text])))
);
CREATE INDEX bank_trades_symbol ON public.bank_trades USING btree (user_id, symbol, created_at);
CREATE INDEX bank_trades_user ON public.bank_trades USING btree (user_id, created_at);

CREATE TABLE bank_transactions (
  id uuid NOT NULL,
  seq bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  account_id uuid NOT NULL,
  kind text NOT NULL,
  amount_cents bigint NOT NULL,
  balance_after_cents bigint NOT NULL,
  description text NOT NULL,
  memo text NOT NULL DEFAULT ''::text,
  counterparty text NOT NULL DEFAULT ''::text,
  transfer_id uuid,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_transactions_pkey PRIMARY KEY (id),
  CONSTRAINT bank_transactions_account_id_fkey FOREIGN KEY (account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_transactions_transfer_id_fkey FOREIGN KEY (transfer_id) REFERENCES bank_transfers(id) ON DELETE SET NULL,
  CONSTRAINT bank_transactions_kind CHECK ((kind = ANY (ARRAY['opening'::text, 'deposit'::text, 'transfer_in'::text, 'transfer_out'::text, 'bill_payment'::text, 'loan_disbursement'::text, 'crypto_buy'::text, 'crypto_sell'::text, 'card_purchase'::text])))
);
CREATE INDEX bank_transactions_account ON public.bank_transactions USING btree (account_id, created_at, seq);

CREATE TABLE bank_transfers (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  from_account_id uuid NOT NULL,
  to_account_id uuid NOT NULL,
  amount_cents bigint NOT NULL,
  memo text NOT NULL DEFAULT ''::text,
  idempotency_key text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_transfers_pkey PRIMARY KEY (id),
  CONSTRAINT bank_transfers_user_id_idempotency_key_key UNIQUE (user_id, idempotency_key),
  CONSTRAINT bank_transfers_from_account_id_fkey FOREIGN KEY (from_account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_transfers_to_account_id_fkey FOREIGN KEY (to_account_id) REFERENCES bank_money_accounts(id) ON DELETE CASCADE,
  CONSTRAINT bank_transfers_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE
);

CREATE TABLE bank_users (
  id uuid NOT NULL,
  email text NOT NULL,
  full_name text NOT NULL,
  password_hash text NOT NULL,
  role text NOT NULL DEFAULT 'customer'::text,
  status text NOT NULL DEFAULT 'active'::text,
  is_demo boolean NOT NULL DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_users_pkey PRIMARY KEY (id),
  CONSTRAINT bank_users_email_key UNIQUE (email),
  CONSTRAINT bank_users_role_check CHECK ((role = ANY (ARRAY['customer'::text, 'support'::text, 'admin'::text]))),
  CONSTRAINT bank_users_status_check CHECK ((status = ANY (ARRAY['active'::text, 'locked'::text])))
);

CREATE TABLE bank_wallet_sends (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  to_address text NOT NULL,
  to_user_id uuid,
  quantity_atoms bigint NOT NULL,
  fee_atoms bigint NOT NULL,
  memo text NOT NULL DEFAULT ''::text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_wallet_sends_pkey PRIMARY KEY (id),
  CONSTRAINT bank_wallet_sends_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_wallet_sends_to_user_id_fkey FOREIGN KEY (to_user_id) REFERENCES bank_users(id) ON DELETE SET NULL,
  CONSTRAINT bank_wallet_sends_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE,
  CONSTRAINT bank_wallet_sends_fee_atoms_check CHECK ((fee_atoms >= 0)),
  CONSTRAINT bank_wallet_sends_quantity_atoms_check CHECK ((quantity_atoms > 0))
);
CREATE INDEX bank_wallet_sends_to ON public.bank_wallet_sends USING btree (to_user_id, created_at);
CREATE INDEX bank_wallet_sends_user ON public.bank_wallet_sends USING btree (user_id, created_at);

CREATE TABLE bank_wallets (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  symbol text NOT NULL,
  address text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT bank_wallets_pkey PRIMARY KEY (id),
  CONSTRAINT bank_wallets_address_key UNIQUE (address),
  CONSTRAINT bank_wallets_user_id_symbol_key UNIQUE (user_id, symbol),
  CONSTRAINT bank_wallets_symbol_fkey FOREIGN KEY (symbol) REFERENCES bank_coins(symbol) ON DELETE CASCADE,
  CONSTRAINT bank_wallets_user_id_fkey FOREIGN KEY (user_id) REFERENCES bank_users(id) ON DELETE CASCADE
);
CREATE INDEX bank_wallets_address ON public.bank_wallets USING btree (address);
